// HBM-OWN/SMH2 r5 (10-21, RELEASE_TREE H.STA.BLK.14.6): soft children of the REGIONAL smh_attn halves (ot_hbm_smh_rp5*_flat,
// generated by tools/hbm_sm_repack_1015/rp5_gen.py).  The rp4a attention leaf core (ot_rp4a_leaf_core, OS = 1) is cut at
// its register stages into region-local soft children so that every hard child is a DIRECT instance of the half and the
// half can be landed by tools/landed_parent/lp.py (x-store region / column region / merge+gather region, one clock root
// each, every region crossing a 4-slot fixed-latency landing ring):
//   ot_rp5_xq   x-store output registers (g_xo: q_*, kept input_pv / attn_column copies, PV broadcast select) + the operand
//               registers (bv .. fx, publish0, fold0*) -> three registered bundles bb / fb / pb (the landing sources)
//   ot_rp5_pub  publication delay line (kept rpp copies) + slot select + published_h128 (static attn_row / attn_column)
//   ot_rp5_go   result registers (g_go) + the G1 gather select -> g
//   ot_rp5_rst  regional reset copy: N kept stages then NC kept copies (depth N + 1 after the lp regional run)
//   ot_rp5_pad  N plain register stages (N = 0: wire)
//   ot_rp5_merge PV merge wrapper (closed config SAFE 2 / TURNREG 1 / PUBLISH 1; OT_RP4A_HARD: no parameters on the hard view)
// Every module is cycle-identical to the matching part of ot_rp4a_leaf_core (rtl/hbm_accel/sm/repack/h2a/ot_hbm_smh_rp4ah.sv).
`timescale 1ns/1ps

module ot_rp5_rst #(parameter integer N = 0, parameter integer NC = 1) (input wire clk, input wire rst_n, output wire [NC-1:0] r);
    generate if (N == 0) begin : g_n0
        (* keep *) reg [NC-1:0] c;
        always @(posedge clk) c <= {NC{rst_n}};
        assign r = c;
    end else begin : g_n
        (* keep *) reg [N-1:0] s;
        (* keep *) reg [NC-1:0] c;
        always @(posedge clk) begin s <= {s, rst_n}; c <= {NC{s[N-1]}}; end
        assign r = c;
    end endgenerate
endmodule

module ot_rp5_pad #(parameter integer W = 1, parameter integer N = 1) (input wire clk, input wire [W-1:0] d, output wire [W-1:0] q);
    generate if (N == 0) begin : g_wire
        assign q = d;
    end else begin : g_reg
        reg [W-1:0] r [0:N-1];
        integer j;
        always @(posedge clk) begin
            r[0] <= d;
            for (j = 1; j < N; j = j + 1) r[j] <= r[j - 1];
        end
        assign q = r[N-1];
    end endgenerate
endmodule

// bb = {bv, bfirst, blast, bfp4, btag[15:0], bw[531:0], bx[531:0]}                      (1084)
// fb = {fv, ffirst, fqlast, fplast, frfirst, frlast, ftag[15:0], fw[255:0], fx[255:0]}  (534)
// pp = publish0[4:0]                                                                    (5)
// pf = {fold0, fold0_a[2:0], fold0_b[2:0]}                                              (7)
module ot_rp5_xq (input wire clk, input wire rst_n, input wire [4:0] at,
    input wire x_iv_b, input wire x_iv_f, input wire x_ifirst, input wire x_ilast, input wire x_ifp4,
    input wire [15:0] x_itag, input wire [787:0] x_iw, input wire [787:0] x_ix,
    input wire x_ifirst_e, input wire x_ilast_e, input wire [15:0] x_itag_e,
    output wire [1083:0] bb, output wire [533:0] fb, output wire [4:0] pp, output wire [6:0] pf);
    localparam integer LBS = 2, TAGW = 16, NIPV = 24;
    wire [2:0] attn_column = at[2:0];
    reg q_iv_b, q_iv_f, q_ifirst, q_ilast, q_ifp4, q_ifirst_e, q_ilast_e;
    reg [TAGW-1:0] q_itag, q_itag_e;
    reg [787:0] q_iw, q_ix;
    (* keep *) reg [NIPV-1:0] k_ivf, k_fp4, k_w129;
    reg [7:0] oh;
    (* keep *) reg [7:0] k_oh [0:15];
    integer i;
    always @(posedge clk) begin
        q_iv_b <= x_iv_b; q_iv_f <= x_iv_f; q_ifirst <= x_ifirst; q_ilast <= x_ilast; q_ifp4 <= x_ifp4;
        q_ifirst_e <= x_ifirst_e; q_ilast_e <= x_ilast_e; q_itag <= x_itag; q_itag_e <= x_itag_e; q_iw <= x_iw; q_ix <= x_ix;
        k_ivf <= {NIPV{x_iv_f}}; k_fp4 <= {NIPV{x_ifp4}}; k_w129 <= {NIPV{x_iw[129]}};
        for (i = 0; i < 8; i = i + 1) oh[i] <= (attn_column == i[2:0]);
        for (i = 0; i < 16; i = i + 1) k_oh[i] <= oh;
    end
    wire [255:0] ipv, pvx;
    genvar s, b, c;
    generate
        for (s = 0; s < 256; s = s + 1) begin : g_ipv
            assign ipv[s] = k_ivf[(s * NIPV) / 256] && k_fp4[(s * NIPV) / 256] && k_w129[(s * NIPV) / 256];
        end
        for (s = 0; s < 16; s = s + 1) begin : g_bw
            for (b = 0; b < 16; b = b + 1) begin : g_b
                wire [7:0] t;
                for (c = 0; c < 8; c = c + 1) begin : g_c
                    assign t[c] = k_oh[s][c] & q_iw[16*c + b];
                end
                assign pvx[16*s + b] = |t;
            end
        end
    endgenerate
    wire marker = q_iv_f && q_ifp4;
    wire input_pv = marker && q_iw[129];
    wire input_arithmetic = q_iv_f && (!marker || q_iw[137]);
    reg bv, bfirst, blast, bfp4, fv, ffirst, fqlast, fplast, frfirst, frlast;
    reg [TAGW-1:0] btag, ftag;
    reg [LBS*266-1:0] bw, bx;
    reg [255:0] fw, fx;
    reg [4:0] publish0;
    reg fold0; reg [2:0] fold0_a, fold0_b;
    integer fs;
    reg [255:0] fx_n;
    always @* for (fs = 0; fs < 256; fs = fs + 1) fx_n[fs] = ipv[fs] ? pvx[fs] : q_ix[LBS*266 + fs];
    always @(posedge clk)
        if (!rst_n) begin bv <= 0; fv <= 0; publish0 <= 0; fold0 <= 0; end
        else begin
            bv <= q_iv_b; fv <= input_arithmetic;
            publish0 <= {q_iw[145], marker && q_iw[134], q_iw[131], q_iw[136:135]};
            fold0 <= marker && q_iw[138];
        end
    always @(posedge clk) begin
        bfirst <= q_ifirst; blast <= q_ilast; bfp4 <= q_ifp4; btag <= q_itag;
        bw <= q_iw[0 +: LBS*266]; bx <= q_ix[0 +: LBS*266];
        fold0_a <= q_iw[141:139]; fold0_b <= q_iw[144:142];
        ffirst <= q_ifirst_e; fqlast <= q_ilast_e && !input_pv; fplast <= q_ilast_e && input_pv;
        frfirst <= q_iw[132]; frlast <= q_iw[133]; ftag <= q_itag_e;
        fw <= q_iw[LBS*266 +: 256];
        fx <= fx_n;
    end
    assign bb = {bv, bfirst, blast, bfp4, btag, bw, bx};
    assign fb = {fv, ffirst, fqlast, fplast, frfirst, frlast, ftag, fw, fx};
    assign pp = publish0;
    assign pf = {fold0, fold0_a, fold0_b};
endmodule

// publication delay line: static tap {attn_row, 4'b0} (0 / 16 / 32 / 48); rst_n is ONE stage before the leaf's rpp copies
// (the 16 kept copies are this module's own register, as ot_rp4a_leaf_core OS = 1)
module ot_rp5_pub (input wire clk, input wire rst_n, input wire [4:0] at, input wire [4:0] pp,
    output wire pub_start, output wire [2:0] pub_slot, output wire published_h128);
    wire [2:0] attn_column = at[2:0];
    wire [1:0] attn_row = at[4:3];
    (* keep *) reg [15:0] rpp;
    always @(posedge clk) rpp <= {16{rst_n}};
    reg [4:0] pub_pipe [0:48];
    integer d;
    always @(posedge clk)
        for (d = 0; d < 49; d = d + 1)
            if (!rpp[d % 16]) pub_pipe[d] <= 0;
            else pub_pipe[d] <= (d == 0) ? pp : pub_pipe[(d == 0) ? 0 : d - 1];
    wire [4:0] pc = pub_pipe[{attn_row, 4'b0000}];
    assign pub_slot = pc[2] ? (pc[4] ? {2'b00, attn_column[0]} : {attn_column[0], pc[1:0]}) : attn_column;
    assign pub_start = pc[3];
    reg ph;
    always @(posedge clk) if (pc[3]) ph <= pc[2];
    assign published_h128 = ph;
endmodule

// result registers + G1 gather select (ot_rp4a_leaf_core g_go + the g select); g = {gv, gf, gy, gt}
module ot_rp5_go (input wire clk, input wire rst_n, input wire [4:0] at,
    input wire bov, input wire [31:0] by, input wire [15:0] bt, input wire bfault,
    input wire fov, input wire [31:0] fy, input wire [15:0] ft, input wire qf,
    input wire mf, input wire ps_v, input wire [31:0] ps_data, input wire [3:0] ps_word, input wire [2:0] ps_slot,
    input wire published_h128, output wire [49:0] g);
    localparam integer TAGW = 16;
    wire [1:0] attn_row = at[4:3];
    wire ffault = qf | mf;
    wire [11:0] scalar_row = published_h128 ? {4'd0, ps_slot[1:0], attn_row, ps_word} : {6'd0, attn_row, ps_word};
    (* keep *) reg [6:0] k_b, k_p;
    (* keep *) reg [0:0] k_f;
    reg [31:0] q_by, q_fy, q_pd;
    reg [TAGW-1:0] q_bt, q_ft;
    reg [11:0] q_sr;
    reg q_bf, q_ff;
    always @(posedge clk) begin
        k_b <= {7{bov}}; k_f <= fov; k_p <= {7{ps_v}};
        q_by <= by; q_fy <= fy; q_pd <= ps_data; q_bt <= bt; q_ft <= ft; q_sr <= scalar_row; q_bf <= bfault; q_ff <= ffault;
    end
    reg gv_q, gf_q;
    reg [31:0] gy_q;
    reg [TAGW-1:0] gt_q;
    always @(posedge clk)
        if (!rst_n) begin gv_q <= 0; gf_q <= 0; end
        else begin gv_q <= k_b[0] | k_f[0] | k_p[0]; gf_q <= q_bf | q_ff | (k_b[0] && k_f[0]) | (k_p[0] && (k_b[0] || k_f[0])); end
    wire [TAGW-1:0] gpt = {q_sr, 1'b1, 3'd0};
    integer gb;
    always @(posedge clk) begin
        for (gb = 0; gb < 32; gb = gb + 1) gy_q[gb] <= k_p[1 + gb / 8] ? q_pd[gb] : k_b[1 + gb / 8] ? q_by[gb] : q_fy[gb];
        for (gb = 0; gb < TAGW; gb = gb + 1) gt_q[gb] <= k_p[5 + gb / 8] ? gpt[gb] : k_b[5 + gb / 8] ? q_bt[gb] : q_ft[gb];
    end
    assign g = {gv_q, gf_q, gy_q, gt_q};
endmodule

// PV merge: the closed config (TAGW 16, LV 4, PUBLISH 1, TURNREG 1, SAFE 2); the hard view carries it (no overrides)
module ot_rp5_merge (input wire clk, input wire rst_n, input wire ev, input wire [511:0] sum, input wire [15:0] tag_d,
    input wire pub_start, input wire [2:0] pub_slot, input wire fold_start, input wire [2:0] fold_a, input wire [2:0] fold_b,
    output wire pub_v, output wire [31:0] pub_data, output wire [3:0] pub_word, output wire [2:0] pub_out_slot,
    output wire [15:0] pub_tag, output wire fault);
    wire pv_v; wire [511:0] pv_y; wire [15:0] pv_tag;
    ot_hbm_sm_pv_merge_s3
`ifndef OT_RP4A_HARD
        #(.TAGW(16), .LV(4), .PUBLISH(1), .TURNREG(1), .SAFE(2))
`endif
        u_merge (.clk(clk), .rst_n(rst_n), .ev(ev), .sum(sum), .tag_d(tag_d), .pv_v(pv_v), .pv_y(pv_y), .pv_tag(pv_tag),
        .fault(fault), .pub_start(pub_start), .pub_slot(pub_slot), .pub_v(pub_v), .pub_data(pub_data), .pub_word(pub_word),
        .pub_out_slot(pub_out_slot), .pub_tag(pub_tag), .fold_start(fold_start), .fold_a(fold_a), .fold_b(fold_b));
endmodule
